cards.secondary:
{% set forecast = states('sensor.solcast_pv_forecast_forecast_remaining_today')|float(0) %}
{% set battery = states('sensor.envoy_482543015950_battery')|float(0) %}
{% set hour = now().hour %}
{% set constraint = states('sensor.ura_energy_coordinator_hvac_constraint') %}
{% if constraint not in ['normal', 'unknown'] %}
🌡️ HVAC: {{ constraint | replace('_',' ') | title }}
{% endif %}
{% if forecast > 10 and battery < 90 %}
🔋 Batteries charging — {{ forecast|round(1) }} kWh solar remaining
{% endif %}
{% if forecast > 5 and hour < 16 %}
🚗 EV Charging Window — optimal until 4 PM
{% endif %}
{% if battery > 80 and hour >= 17 %}
❄️ Pre-cool opportunity — Battery at {{ battery }}%
{% endif %}
{% if forecast < 3 %}
⚠️ Low Solar — defer heavy loads
{% elif forecast <= 5 %}
☁️ Moderate Solar — {{ forecast|round(1) }} kWh remaining
{% else %}
☀️ {{ forecast|round(1) }} kWh solar remaining today
{% endif %}

filters.fn:
({ ys, xs, hass, entity }) => {
  const data = [];
  const fc = hass.states[entity.entity_id].attributes.detailedHourly;
  if (fc) {
    fc.forEach(f => {
      data.push({
        x: new Date(f.period_start).getTime(),
        y: f.pv_estimate
      });
    });
  }
  return {
    xs: data.map(d => d.x),
    ys: data.map(d => d.y)
  };
}

